    let parts = str_split(s, "\n")
    let n = len(parts)
    if n > 0 && str_len(parts[n - 1]) == 0 { arr_take(parts, n - 1) } else { parts }
}

fn valid_qty(s: str) -> bool {
    if len(s) == 0 { return false }
    for i in 0..len(s) {
        let c = char_at(s, i)
        if c < 48 || c > 57 { return false }
    }
    parse_int_or(s, 0) > 0
}

